#include "net_l2.h"
static uint16_t be16(const uint8_t*p){return(uint16_t)(((uint16_t)p[0]<<8)|p[1]);}
int net_ethernet_parse(const uint8_t*p,uint32_t n,struct net_eth_view*out){if(!p||!out||n<14)return -1;for(uint32_t i=0;i<6;i++){out->destination[i]=p[i];out->source[i]=p[6+i];}uint16_t type=be16(p+12);uint32_t off=14;if(type==0x8100||type==0x88a8){if(n<18)return -1;type=be16(p+16);off=18;if(type==0x8100||type==0x88a8)return -1;}if(type<0x0600)return -1;out->ethertype=type;out->payload=p+off;out->payload_length=n-off;return 0;}
int net_arp_parse(const uint8_t*p,uint32_t n,struct net_arp_view*out){if(!p||!out||n<8)return -1;uint16_t h=be16(p),proto=be16(p+2);uint8_t hl=p[4],pl=p[5];uint32_t need=8U+2U*((uint32_t)hl+pl);if(!hl||!pl||need>n||need>512)return -1;out->hardware_type=h;out->protocol_type=proto;out->hardware_length=hl;out->protocol_length=pl;out->operation=(uint8_t)be16(p+6);if(be16(p+6)>2||be16(p+6)==0)return -1;out->sender_hardware=p+8;out->sender_protocol=p+8+hl;out->target_hardware=p+8+hl+pl;out->target_protocol=p+8+2U*hl+pl;return 0;}
